# Gunicorn configuration for Scholar System (generated by the YunoHost package)
import multiprocessing

bind = "127.0.0.1:__PORT__"
# Threaded workers keep exam autosaves responsive with a modest memory footprint.
worker_class = "gthread"
workers = min(multiprocessing.cpu_count() + 1, 5)
threads = 4
timeout = 120
graceful_timeout = 30
max_requests = 2000
max_requests_jitter = 200
forwarded_allow_ips = "127.0.0.1"
accesslog = None
errorlog = "-"
loglevel = "info"
proc_name = "__APP__"
